```go
package cart

// DiscountType for codes
type DiscountType int

const (
	DiscountPercent DiscountType = iota
	DiscountFixed
)

// CartItem is item in cart
type CartItem struct {
	SKU      string
	Name     string
	Price    int
	Quantity int
}

// Cart holds items
type Cart struct {
	items        map[string]*CartItem
	discountCode string
	discountType DiscountType
	discountVal  int
	hasDiscount  bool
}

// NewCart makes empty cart
func NewCart() *Cart {
	return &Cart{
		items: make(map[string]*CartItem),
	}
}

// AddItem puts thing in cart
func (c *Cart) AddItem(sku, name string, price, qty int) {
	if item, ok := c.items[sku]; ok {
		item.Quantity += qty
	} else {
		c.items[sku] = &CartItem{
			SKU:      sku,
			Name:     name,
			Price:    price,
			Quantity: qty,
		}
	}
}

// RemoveItem takes thing out
func (c *Cart) RemoveItem(sku string, qty int) {
	if item, ok := c.items[sku]; ok {
		item.Quantity -= qty
		if item.Quantity <= 0 {
			delete(c.items, sku)
		}
	}
}

// Clear empties cart. Like eating all cookies.
func (c *Cart) Clear() {
	c.items = make(map[string]*CartItem)
}

// ItemCount counts all items
func (c *Cart) ItemCount() int {
	count := 0
	for _, item := range c.items {
		count += item.Quantity
	}
	return count
}

// Subtotal before discount
func (c *Cart) Subtotal() int {
	total := 0
	for _, item := range c.items {
		total += item.Price * item.Quantity
	}
	return total
}

// Total after discount
func (c *Cart) Total() int {
	sub := c.Subtotal()
	if !c.hasDiscount {
		return sub
	}
	if c.discountType == DiscountPercent {
		return sub - (sub * c.discountVal / 100)
	}
	// Fixed
	if c.discountVal >= sub {
		return 0
	}
	return sub - c.discountVal
}

// DiscountAmount shows savings
func (c *Cart) DiscountAmount() int {
	return c.Subtotal() - c.Total()
}

// ApplyDiscount adds code
func (c *Cart) ApplyDiscount(code string, dtype DiscountType, val int) {
	c.discountCode = code
	c.discountType = dtype
	c.discountVal = val
	c.hasDiscount = true
}

// RemoveDiscount removes code
func (c *Cart) RemoveDiscount() {
	c.hasDiscount = false
	c.discountCode = ""
	c.discountVal = 0
}

// GetItems returns items
func (c *Cart) GetItems() []CartItem {
	items := make([]CartItem, 0, len(c.items))
	for _, item := range c.items {
		items = append(items, *item)
	}
	return items
}

// HasItem checks if SKU in cart
func (c *Cart) HasItem(sku string) bool {
	_, ok := c.items[sku]
	return ok
}

// GetQuantity gets how many of SKU
func (c *Cart) GetQuantity(sku string) int {
	if item, ok := c.items[sku]; ok {
		return item.Quantity
	}
	return 0
}
```

